    def from_config(cls, yaml_path: str) -> 'ConcatStep':
        with open(yaml_path, 'r') as f:
            config = yaml.safe_load(f)
        return cls(**config)

    async def process(self, input_data: dict, **kwargs) -> dict:
        parts = input_data["parts"]
        sep = input_data.get("sep", "")
        joined = sep.join(parts)
        return {"joined": joined}

from nanobrain.core.step import BaseStep
from typing import Dict, List

class DedupePreserveOrderStep(BaseStep):
    async def process(self, input_data: Dict[str, List], **kwargs) -> Dict[str, List]:
        seen = set()
        unique_items = []
        for item in input_data["items"]:
            if item not in seen:
                seen.add(item)
                unique_items.append(item)
        return {"unique": unique_items}

